alter table public.clients add column if not exists internal_kind text; alter table public.clients drop constraint if exists clients_internal_kind_check; alter table public.clients add constraint clients_internal_kind_check check (internal_kind is null or internal_kind in ('personal', 'business')); create unique index if not exists clients_internal_kind_key on public.clients (internal_kind) where internal_kind is not null; insert into public.clients (name, stage, service, internal_kind) select 'Personal brand', 'active', 'Your own content', 'personal' where not exists (select 1 from public.clients where internal_kind = 'personal'); insert into public.clients (name, stage, service, internal_kind) select 'Advatar', 'active', 'The business''s own content', 'business' where not exists (select 1 from public.clients where internal_kind = 'business'); create or replace function public.set_own_content_access(target uuid, allow boolean) returns void language plpgsql security definer set search_path = public as $$ begin if not public.is_ceo_role() then raise exception 'Only the CEO can change who works on your own content.'; end if; if not exists (select 1 from public.profiles where id = target and role in ('operations_manager', 'staff', 'videographer')) then raise exception 'That person is not on the team.'; end if; if allow then insert into public.client_staff (client_id, staff_id, role_on_client) select c.id, target, 'Your content' from public.clients c where c.internal_kind is not null on conflict (client_id, staff_id) do nothing; else delete from public.client_staff cs using public.clients c where cs.client_id = c.id and c.internal_kind is not null and cs.staff_id = target; end if; end; $$; revoke all on function public.set_own_content_access(uuid, boolean) from public; grant execute on function public.set_own_content_access(uuid, boolean) to authenticated; alter table public.tasks add column if not exists video_id uuid references public.content_videos (id) on delete cascade, add column if not exists step text; alter table public.tasks drop constraint if exists tasks_step_check; alter table public.tasks add constraint tasks_step_check check ( (video_id is null and step is null) or (video_id is not null and step in ('film', 'edit', 'submit', 'post')) ); create unique index if not exists tasks_video_step_key on public.tasks (video_id, step) where video_id is not null; create or replace function public.video_step_dates(publish date) returns table (step text, step_order int, due date) language sql immutable as $$ with t as ( select publish - (extract(isodow from publish)::int - 1) - 3 as target ) select x.step, x.step_order, x.due from t, lateral ( values ('film', 1, t.target - 4), ('edit', 2, t.target - 1), ('submit', 3, t.target), ('post', 4, publish) ) as x (step, step_order, due); $$; grant execute on function public.video_step_dates(date) to authenticated; create or replace function public.video_step_assignee(target_client uuid) returns uuid language sql stable security definer set search_path = public as $$ select coalesce( ( select cs.staff_id from public.client_staff cs join public.profiles p on p.id = cs.staff_id where cs.client_id = target_client and p.role in ('videographer', 'staff', 'operations_manager') order by case p.role when 'videographer' then 0 when 'staff' then 1 else 2 end, cs.created_at limit 1 ), ( select p.id from public.profiles p where p.role = 'ceo' and exists (select 1 from public.clients c where c.id = target_client and c.internal_kind is not null) order by p.created_at limit 1 ) ); $$; create or replace function public.sync_video_steps(target_video uuid) returns void language plpgsql security definer set search_path = public as $$ declare v record; made boolean := false; shared boolean := false; label text; who uuid; s record; begin select cv.id, cv.client_id, cv.publish_on, cv.title, cv.pillar, cv.submission_id, cv.posted_at into v from public.content_videos cv where cv.id = target_video; if not found then return; end if; if v.publish_on is null then delete from public.tasks where video_id = v.id and not done; return; end if; if v.submission_id is not null then select coalesce(sub.current_version, 0) >= 1, coalesce(sub.visibility, '') = 'team_and_client' into made, shared from public.submissions sub where sub.id = v.submission_id; made := coalesce(made, false); shared := coalesce(shared, false) and made; end if; label := coalesce(nullif(btrim(v.title), ''), nullif(btrim(v.pillar), '') || ' video', 'Video') || ' (' || to_char(v.publish_on, 'FMDD Mon') || ')'; who := public.video_step_assignee(v.client_id); for s in select * from public.video_step_dates(v.publish_on) loop insert into public.tasks (client_id, assigned_to, text, due_date, done, video_id, step) values ( v.client_id, who, case s.step when 'film' then 'Film: ' when 'edit' then 'Edit: ' when 'submit' then 'Send for approval: ' else 'Post: ' end || label, s.due, case s.step when 'post' then v.posted_at is not null when 'submit' then v.posted_at is not null or shared else v.posted_at is not null or made end, v.id, s.step ) on conflict (video_id, step) where video_id is not null do update set client_id = excluded.client_id, text = excluded.text, due_date = excluded.due_date, assigned_to = coalesce(public.tasks.assigned_to, excluded.assigned_to), done = case when excluded.step = 'post' then excluded.done else public.tasks.done or excluded.done end; end loop; end; $$; create or replace function public.content_videos_sync_steps() returns trigger language plpgsql security definer set search_path = public as $$ begin perform public.sync_video_steps(new.id); return new; end; $$; drop trigger if exists content_videos_sync_steps on public.content_videos; create trigger content_videos_sync_steps after insert or update of publish_on, title, pillar, submission_id, posted_at, client_id on public.content_videos for each row execute procedure public.content_videos_sync_steps(); create or replace function public.submissions_sync_steps() returns trigger language plpgsql security definer set search_path = public as $$ declare vid uuid; begin for vid in select id from public.content_videos where submission_id = new.id loop perform public.sync_video_steps(vid); end loop; return new; end; $$; drop trigger if exists submissions_sync_steps on public.submissions; create trigger submissions_sync_steps after update of visibility, current_version on public.submissions for each row when (old.visibility is distinct from new.visibility or old.current_version is distinct from new.current_version) execute procedure public.submissions_sync_steps(); create or replace function public.tasks_post_step_marks_video() returns trigger language plpgsql security definer set search_path = public as $$ begin update public.content_videos set posted_at = case when new.done then coalesce(posted_at, now()) else null end where id = new.video_id and (posted_at is not null) is distinct from new.done; return new; end; $$; drop trigger if exists tasks_post_step_marks_video on public.tasks; create trigger tasks_post_step_marks_video after update of done on public.tasks for each row when (new.step = 'post' and new.video_id is not null and old.done is distinct from new.done) execute procedure public.tasks_post_step_marks_video(); create or replace function public.client_staff_moves_video_steps() returns trigger language plpgsql security definer set search_path = public as $$ begin if tg_op = 'INSERT' then update public.tasks set assigned_to = public.video_step_assignee(new.client_id) where client_id = new.client_id and video_id is not null and not done and assigned_to is null; return new; end if; update public.tasks set assigned_to = public.video_step_assignee(old.client_id) where client_id = old.client_id and video_id is not null and not done and assigned_to = old.staff_id; return old; end; $$; drop trigger if exists client_staff_moves_video_steps on public.client_staff; create trigger client_staff_moves_video_steps after insert or delete on public.client_staff for each row execute procedure public.client_staff_moves_video_steps(); create or replace function public.notify_task_change() returns trigger language plpgsql security definer set search_path = public as $$ declare client_name text; due_text text; begin if new.video_id is not null then return new; end if; if new.assigned_to is null then return new; end if; if new.client_id is not null then select name into client_name from public.clients where id = new.client_id; end if; due_text := case when new.due_date is null then null else 'Due ' || to_char(new.due_date, 'FMDD FMMonth') end; if tg_op = 'INSERT' then perform public.notify_user( new.assigned_to, 'task_assigned', 'New task: ' || new.text, concat_ws(' ' || chr(183) || ' ', client_name, due_text), '/app/my-work' ); return new; end if; if new.assigned_to is distinct from old.assigned_to then perform public.notify_user( new.assigned_to, 'task_assigned', 'A task was passed to you: ' || new.text, concat_ws(' ' || chr(183) || ' ', client_name, due_text), '/app/my-work' ); elsif new.due_date is distinct from old.due_date then perform public.notify_user( new.assigned_to, 'task_deadline_changed', 'Deadline changed: ' || new.text, case when new.due_date is null then 'The due date was removed.' else due_text end, '/app/my-work' ); elsif new.text is distinct from old.text then perform public.notify_user( new.assigned_to, 'task_updated', 'A task of yours was reworded', new.text, '/app/my-work' ); end if; return new; end; $$; do $$ declare vid uuid; begin for vid in select id from public.content_videos where publish_on >= current_date - 7 and posted_at is null loop perform public.sync_video_steps(vid); end loop; end; $$; create table if not exists public.scripts ( id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients (id) on delete cascade, title text not null check (char_length(btrim(title)) between 1 and 200), pillar text check (pillar is null or char_length(pillar) <= 80), hook text check (hook is null or char_length(hook) <= 2000), body text check (body is null or char_length(body) <= 8000), cta text check (cta is null or char_length(cta) <= 2000), notes text check (notes is null or char_length(notes) <= 4000), video_id uuid references public.content_videos (id) on delete set null, created_by uuid references public.profiles (id) on delete set null, updated_by uuid references public.profiles (id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); create index if not exists scripts_client_idx on public.scripts (client_id, created_at desc); create unique index if not exists scripts_video_key on public.scripts (video_id) where video_id is not null; alter table public.scripts enable row level security; drop policy if exists "scripts: team on client" on public.scripts; create policy "scripts: team on client" on public.scripts for all using (public.current_role() <> 'client' and public.can_see_client(client_id)) with check (public.current_role() <> 'client' and public.can_see_client(client_id)); grant select, insert, update, delete on public.scripts to authenticated; create or replace function public.scripts_copy_to_video() returns trigger language plpgsql security definer set search_path = public as $$ begin new.updated_at := now(); if new.video_id is not null then if not exists (select 1 from public.content_videos where id = new.video_id and client_id = new.client_id) then raise exception 'That video belongs to a different client.'; end if; update public.content_videos set hook = new.hook, body = new.body, cta = new.cta, title = coalesce(nullif(btrim(title), ''), new.title), pillar = coalesce(nullif(btrim(pillar), ''), new.pillar) where id = new.video_id; end if; return new; end; $$; drop trigger if exists scripts_copy_to_video on public.scripts; create trigger scripts_copy_to_video before insert or update on public.scripts for each row execute procedure public.scripts_copy_to_video(); create or replace function public.attach_script(target_script uuid, target_video uuid) returns void language plpgsql security definer set search_path = public as $$ declare sc record; begin select id, client_id into sc from public.scripts where id = target_script; if not found or public.current_role() = 'client' or not public.can_see_client(sc.client_id) then raise exception 'Script not found.'; end if; if target_video is null then update public.scripts set video_id = null, updated_by = auth.uid() where id = target_script; return; end if; if not exists (select 1 from public.content_videos where id = target_video and client_id = sc.client_id) then raise exception 'That video belongs to a different client.'; end if; update public.scripts set video_id = null where video_id = target_video and id <> target_script; update public.scripts set video_id = target_video, updated_by = auth.uid() where id = target_script; end; $$; revoke all on function public.attach_script(uuid, uuid) from public; grant execute on function public.attach_script(uuid, uuid) to authenticated;
